import { Component, computed, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { ReportService } from '../../core/services/domain.services';
import { AuthService } from '../../core/services/auth.service';
import { Dashboard } from '../../core/models/models';
import { IconComponent } from '../../shared/icon/icon.component';
import { MoneyPipe } from '../../shared/pipes/money.pipe';
import { OrderStatusBadge } from '../../shared/ui/badges';
import { LoadingComponent, EmptyStateComponent } from '../../shared/ui/misc';
import { LineChartComponent, DonutChartComponent, BarChartComponent, DonutSegment } from '../../shared/charts/charts';

const STATUS_COLORS: Record<string, string> = {
  Pending: '#F59E0B', Preparing: '#2563EB', Ready: '#16A34A', Completed: '#15803D', Cancelled: '#DC2626',
};

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, RouterLink, IconComponent, MoneyPipe, OrderStatusBadge,
    LoadingComponent, EmptyStateComponent, LineChartComponent, DonutChartComponent, BarChartComponent],
  templateUrl: './dashboard.component.html',
  styleUrl: './dashboard.component.scss',
})
export class DashboardComponent {
  private reports = inject(ReportService);
  private auth = inject(AuthService);

  loading = signal(true);
  data = signal<Dashboard | null>(null);
  now = new Date();

  salesSeries = computed(() => (this.data()?.salesOverview ?? []).map(p => ({ label: p.label, value: p.sales })));
  statusSegments = computed<DonutSegment[]>(() =>
    (this.data()?.ordersByStatus ?? []).map(s => ({ label: s.status, value: s.count, color: STATUS_COLORS[s.status] ?? '#94A3B8' })));
  topFood = computed(() => (this.data()?.topSelling ?? []).map(t => ({ label: t.name, value: t.quantitySold })));

  constructor() {
    this.reports.dashboard().subscribe({
      next: d => { this.data.set(d); this.loading.set(false); },
      error: () => this.loading.set(false),
    });
  }

  greeting(): string {
    const h = this.now.getHours();
    return h < 12 ? 'Good Morning' : h < 17 ? 'Good Afternoon' : 'Good Evening';
  }
  firstName(): string { return (this.auth.user()?.fullName || '').split(' ')[0]; }
}
